const raw = $input.first().json;
const body = raw.body || raw;
const question = body.question || body.query || body.q || '';

if (!question.trim()) {
  return [{ json: { error: 'No question provided', status: 'error' } }];
}

return [{ json: { question: question.trim() } }];

const response = $input.first().json;
const question = $('Extract Question').first().json.question;

let embedding;
if (response.data?.[0]?.embedding) {
  embedding = response.data[0].embedding;
} else {
  return [{ json: { error: 'Failed to generate question embedding', question } }];
}

// Format embedding for pgvector cosine similarity query
const embeddingStr = '[' + embedding.join(',') + ']';

return [{ json: {
  question,
  embedding_str: embeddingStr
} }];

const results = $input.first().json;
const question = $('Extract Question').first().json.question;

// Build context from retrieved documents
let context = '';
const sources = [];

if (Array.isArray(results)) {
  results.forEach((doc, i) => {
    context += `[Source ${i+1}] ${doc.title || 'Document'}: ${doc.content}\n\n`;
    sources.push({
      title: doc.title || 'Unknown',
      similarity: doc.similarity ? doc.similarity.toFixed(3) : 'N/A',
      department: doc.department || 'general'
    });
  });
} else {
  context = 'No relevant documents found in the knowledge base.';
}

return [{ json: {
  question,
  context: context.substring(0, 4000),
  sources,
  doc_count: sources.length
} }];

